const crypto = require('node:crypto');
const {
  KIT_ASSETS_BY_KEY,
  defaultStripeRequest,
  isPaidKitSession,
  isValidLiveSessionId,
} = require('./kit-session');

const ENCRYPTED_ASSETS = Object.freeze({"dispute-script-pack.md":{"ciphertext":"","iv":"2OEB/U47ygC0QiKY","tag":"mVvn59ws/T1NWU6nhvhMQQ=="},"dispute-script-pack.pdf":{"ciphertext":"","iv":"lHI6ybFzS6mt60cM","tag":"w3jDeAS5DoQk4H19723KvQ=="},"rental-car-damage-prevention.pdf":{"ciphertext":"","iv":"9ULRV/DgoEEeidhf","tag":"sDxFF8cwRa0edUvk8v6Ntg=="},"time-stamp-defense-checklist.pdf":{"ciphertext":"","iv":"atQskoru1UsNakwH","tag":"h+TFK2mLHLVUjnDIF5uK5Q=="}});

function decodeEncryptionKey(keyBase64) {
  let key;
  try { key = Buffer.from(keyBase64 || '', 'base64'); } catch (_) { key = Buffer.alloc(0); }
  if (key.length !== 32) throw new Error('KIT_ASSET_ENCRYPTION_KEY must decode to a 32-byte key');
  return key;
}

function decryptAssetBlob(blob, keyBase64) {
  if (!blob) throw new Error('Private asset is missing from the function bundle');
  const key = decodeEncryptionKey(keyBase64);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(blob.iv, 'base64'));
  decipher.setAuthTag(Buffer.from(blob.tag, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(blob.ciphertext, 'base64')), decipher.final()]);
}

async function defaultReadAsset(asset) {
  return decryptAssetBlob(ENCRYPTED_ASSETS[asset.storedFilename], process.env.KIT_ASSET_ENCRYPTION_KEY);
}

function setPrivateResponseHeaders(res) {
  res.setHeader('Cache-Control', 'private, no-store, max-age=0');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow, noarchive');
  res.setHeader('Content-Security-Policy', "default-src 'none'; sandbox");
  res.setHeader('Referrer-Policy', 'no-referrer');
}

function createKitDownloadHandler({
  stripeRequest = defaultStripeRequest,
  readAsset = defaultReadAsset,
} = {}) {
  return async function kitDownloadHandler(req, res) {
    setPrivateResponseHeaders(res);
    if (req.method !== 'GET') return res.status(405).json({ error: 'Method not allowed' });

    const assetKey = typeof req.query?.asset === 'string' ? req.query.asset : '';
    const asset = KIT_ASSETS_BY_KEY.get(assetKey);
    if (!asset) return res.status(404).json({ error: 'Asset not found' });

    const sessionId = typeof req.query?.session_id === 'string' ? req.query.session_id : '';
    if (!isValidLiveSessionId(sessionId)) {
      return res.status(400).json({ error: 'Valid checkout session required' });
    }

    try {
      const session = await stripeRequest(`/v1/checkout/sessions/${encodeURIComponent(sessionId)}`);
      if (!isPaidKitSession(session)) {
        return res.status(403).json({ error: 'Paid Emergency Kit checkout required' });
      }

      const content = await readAsset(asset);
      res.setHeader('Content-Type', asset.contentType);
      res.setHeader('Content-Disposition', `attachment; filename="${asset.filename}"`);
      res.setHeader('Content-Length', String(content.length));
      return res.status(200).end(content);
    } catch (error) {
      console.error('[kit-download] fulfillment failed:', error.message);
      return res.status(403).json({ error: 'Download could not be verified' });
    }
  };
}

const handler = createKitDownloadHandler();
module.exports = handler;
module.exports.default = handler;
module.exports.createKitDownloadHandler = createKitDownloadHandler;
module.exports.defaultReadAsset = defaultReadAsset;
module.exports.decryptAssetBlob = decryptAssetBlob;
module.exports.decodeEncryptionKey = decodeEncryptionKey;
module.exports.setPrivateResponseHeaders = setPrivateResponseHeaders;
